import { TestingModule } from '@nestjs/testing';
import { MikroORM } from '@mikro-orm/core';
import { createIntegrationTestModule, cleanDatabase } from './setup';
import { ShipmentEvent } from '../../src/entities/shipment-event.entity';
import { buildShipmentEvent } from '../factories/shipment-event.factory';
import { Shipment } from '../../src/entities/shipment.entity';
import { buildShipment } from '../factories/shipment.factory';

describe('ShipmentEvent Relationships', () => {
  let module: TestingModule;
  let orm: MikroORM;
  let shipmentId: string;

  beforeAll(async () => {
    module = await createIntegrationTestModule();
    orm = module.get(MikroORM);
  });

  beforeEach(async () => {
    const em = orm.em.fork();
    const shipmentEntity = em.create(
      Shipment,
      buildShipment(),
    );
    await em.persistAndFlush(shipmentEntity);
    shipmentId = shipmentEntity.id;
  });

  afterEach(async () => {
    await cleanDatabase(orm);
  });

  afterAll(async () => {
    await module.close();
  });

  describe('belongs_to Shipment', () => {
    it('persists shipment reference', async () => {
      const em = orm.em.fork();
      const data = buildShipmentEvent({ shipment: shipmentId });
      const saved = em.create(ShipmentEvent, data);
      await em.persistAndFlush(saved);
      await em.populate(saved, ['shipment']);
      expect(saved.shipment.id).toBe(shipmentId);
    });

    it('loads parent via relation', async () => {
      const em = orm.em.fork();
      const data = buildShipmentEvent({ shipment: shipmentId });
      const saved = em.create(ShipmentEvent, data);
      await em.persistAndFlush(saved);
      const loaded = await em.findOne(
        ShipmentEvent,
        { id: saved.id },
        { populate: ['shipment'] },
      );
      expect(loaded).not.toBeNull();
      expect(loaded!.shipment).toBeDefined();
      expect(loaded!.shipment.id).toBe(shipmentId);
    });

    it('rejects entity without required shipment', async () => {
      const em = orm.em.fork();
      const data = buildShipmentEvent({ shipment: undefined as unknown as string });
      const row = em.create(ShipmentEvent, data);
      await expect(em.persistAndFlush(row)).rejects.toThrow();
    });
  });
});
